<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class Portfolio extends Model{protected $fillable=['studio_owner_id','slug','name','website_url','about_us','currency_code','status','show_payment_details','cover_disk','cover_object_key','cover_mime_type','cover_size_bytes','cover_width','cover_height','upi_id','upi_phone','bank_name','account_holder_name','account_number','account_type','ifsc'];protected $hidden=['cover_disk','cover_object_key','upi_id','upi_phone','bank_name','account_holder_name','account_number','account_type','ifsc'];protected $casts=['show_payment_details'=>'boolean','cover_size_bytes'=>'integer','upi_id'=>'encrypted','upi_phone'=>'encrypted','bank_name'=>'encrypted','account_holder_name'=>'encrypted','account_number'=>'encrypted','account_type'=>'encrypted','ifsc'=>'encrypted'];public function owner(){return$this->belongsTo(User::class,'studio_owner_id');}public function images(){return$this->hasMany(PortfolioImage::class)->orderBy('sort_order');}public function services(){return$this->hasMany(PortfolioService::class)->orderBy('sort_order');}}
